from collections import defaultdict

def solve_tiles(allow_rot=False, limit=10):
 dims=[d for _,d in shapes]
 choices=[]
 for i,(name,(h,w)) in enumerate(shapes):
  orientations={(h,w)}
  if allow_rot: orientations.add((w,h))
  pl=[]
  for hh,ww in orientations:
   for r in range(20-hh+1):
    for c in range(9-ww+1):
     cells=frozenset((rr,cc) for rr in range(r,r+hh) for cc in range(c,c+ww))
     if cells<=holes: pl.append((i,name,r,c,hh,ww,cells))
  choices.append(pl)
 bycell=defaultdict(list)
 for ps in choices:
  for p in ps:
   for cell in p[-1]: bycell[cell].append(p)
 sols=[]
 def rec(rem,used,placements):
  if not rem:
   if len(used)==len(shapes):
    sols.append(placements.copy())
   return len(sols)>=limit
  best=None; opts=None
  for cell in rem:
   oo=[p for p in bycell[cell] if p[0] not in used and p[-1]<=rem]
   if not opts or len(oo)<len(opts): best,opts=cell,oo
   if not oo: return False
   if len(opts)==1: break
  for p in opts:
   if rec(rem-p[-1],used|{p[0]},placements+[p]): return True
  return False
 rec(frozenset(holes),set(),[])
 return sols
